# Extract raw Glucose and Steps for eligibility check
# Note: indices depend on the numerical_feature_cols defined previously
glucose_idx = numerical_feature_cols.index('num__Glucose')
steps_idx = numerical_feature_cols.index('num__Daily_Steps')

# Simulating 30 days of high consistency (score = 30)
